     display_label, url_path_template, rls_uses_has_permission, is_active, notes, content_role,
     is_scopeable, public_columns, is_link_shareable, organization_id, metadata, version,
     visibility)
select r.id, r.resource_type, r.schema_name, r.table_name, r.id_column, r.owner_column,
       r.is_public_column, r.display_label, r.url_path_template, r.rls_uses_has_permission,
       r.is_active, r.notes, r.content_role, r.is_scopeable, r.public_columns,
       r.is_link_shareable, r.organization_id, r.metadata, r.version, r.visibility::platform.visibility
