    as r(id uuid, resource_type text, schema_name text, table_name text, id_column text,
         owner_column text, is_public_column text, display_label text, url_path_template text,
         rls_uses_has_permission boolean, is_active boolean, notes text, content_role text,
         is_scopeable boolean, public_columns text[], is_link_shareable boolean,
         organization_id uuid, metadata jsonb, version integer, visibility text)
on conflict (resource_type) do nothing;

do $$
declare n int;
begin
    select count(*) into n from platform.shareable_resource_registry;
    if n < 292 or not exists (select 1 from platform.shareable_resource_registry
                               where resource_type = 'record') then
        raise exception 'the sharing registry carries % rows and record is %; main carries 292 and iam.has_access reads this table, so every grant on a record is refused without it',
            n, case when exists (select 1 from platform.shareable_resource_registry where resource_type = 'record')
                    then 'present' else 'ABSENT' end;
    end if;
end $$;
